    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* Shared field parts to compose. */

  .field {
    display: grid;
    /* The field's width, not its input's: an input's default size (about 20
       characters) would otherwise push a narrow form sideways. */
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ui-space-2);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .label {
    justify-self: start;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .shell {
    --edge: var(--ui-border-strong);
    --edge-width: var(--ui-hairline);
    --shell-inset: calc((var(--ui-control-md) - var(--ui-control-sm)) / 2);
    position: relative;
    height: var(--ui-control-md);
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition: box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .shell:hover:not(:focus-within, [data-invalid], [data-disabled], [data-open]) {
      --edge: var(--ui-field-focus);
    }
  }

  .shell:focus-within,
  .shell[data-open] {
    --edge: var(--ui-field-focus);
    --edge-width: 1px;
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition-duration: 0s;
  }

  .shell[data-open] {
    transition-duration: var(--ui-dur-instant);
  }

  .shell[data-invalid] {
    --edge: var(--ui-danger);
  }

  .shell[data-disabled] {
    opacity: 0.5;
  }

  .bare {
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
  }

  .bare::placeholder {
    color: var(--ui-subtle);
  }

  .bare:disabled {
    cursor: default;
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .bare {
      font-size: var(--ui-text-touch);
    }
  }

  /* Inset button. Set its radius where it sits (outer radius less the inset). */
  .inset {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    position: relative;
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--ui-control-sm);
    height: var(--ui-control-sm);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-md) - var(--shell-inset, 4px));
    background: none;
    color: var(--ui-muted);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .inset::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .inset > * {
    position: relative;
  }

  @media (hover: hover) {
    .inset:hover:not(:disabled, [aria-disabled]) {
      color: var(--ui-foreground);
    }
    .inset:hover:not(:disabled, [aria-disabled])::before {
      background: var(--ui-fill);
    }
  }

  .inset:active:not(:disabled, [aria-disabled]) {
    color: var(--ui-foreground);
  }

  .inset:active:not(:disabled, [aria-disabled])::before {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .inset:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
    color: var(--ui-foreground);
  }

  .inset:disabled,
  .inset[aria-disabled] {
    cursor: default;
  }

  /* 32px to look at, 40px to hit. */
  @media (pointer: coarse) {
    .inset::after {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  .message {
    display: grid;
    min-height: var(--ui-leading-md);
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .errorIcon {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 14);
  }

  .error[data-shown] .errorText {
    animation: field-error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes field-error-swap {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .inset:active:not(:disabled, [aria-disabled])::before {
      scale: none;
    }
    .error[data-shown] .errorText {
      animation: none;
    }
  }
}

"use client";

import { useState } from "react";
import { Icon } from "../icons/icons";
import styles from "./field.module.css";

type FieldMessageProps = {
  id: string;
  hint?: string | null;
  error?: string | null;
};

/** Hint or error; the hidden one leaves the description and live region. */
export function FieldMessage({ id, hint, error }: FieldMessageProps) {
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  return (
    <p id={id} className={styles.message} aria-live="polite">
      {hint && (
        <span className={styles.hint} data-shown={!error || undefined}>
          {hint}
        </span>
      )}
      {lastError && (
        <span className={styles.error} data-shown={error ? true : undefined}>
          <Icon name="alert" className={styles.errorIcon} />
          <span key={lastError} className={styles.errorText}>
            {lastError}
          </span>
        </span>
      )}
    </p>
  );
}

@layer theme, base, components, utilities;

@property --inline-dim {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

.errorIcon {
  composes: errorIcon from "../field/field.module.css";
}

@layer components {
  /* Negative margin cancels the padding, so the text sits where plain text would. */
  .root {
    --inline-pad-x: var(--ui-space-2);
    --inline-pad-y: var(--ui-space-1);
    position: relative;
    display: inline-grid;
    box-sizing: border-box;
    max-width: calc(100% + var(--inline-pad-x) * 2);
    margin: calc(var(--inline-pad-y) * -1) calc(var(--inline-pad-x) * -1);
    padding: var(--inline-pad-y) var(--inline-pad-x);
    border-radius: var(--ui-radius-sm);
    --inline-edge: transparent;
    box-shadow: inset 0 0 0 1px var(--inline-edge);
    transition:
      box-shadow var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .root[data-block] {
    display: grid;
    width: fit-content;
  }

  .root[data-editing] {
    --inline-edge: var(--ui-field-focus);
    background: var(--ui-surface);
    transition-duration: 0s;
  }

  .root[data-invalid] {
    --inline-edge: var(--ui-danger);
    transition-duration: var(--ui-dur-fast);
  }

  /* Text and textarea must match type and wrapping exactly, or the overlay drifts. */
  .text,
  .input {
    margin: 0;
    text-wrap: inherit;
    color: inherit;
    font: inherit;
    font-feature-settings: inherit;
    font-variant-numeric: inherit;
    letter-spacing: inherit;
    word-spacing: inherit;
    text-transform: inherit;
    text-align: inherit;
    white-space: break-spaces;
    overflow-wrap: break-word;
  }

  .text {
    grid-area: 1 / 1;
    min-width: 1ch;
    position: relative;
    z-index: 1;
    pointer-events: none;
  }

  .text[data-placeholder] {
    color: var(--ui-subtle);
  }

  .root[data-editing] .text {
    visibility: hidden;
  }

  /* ---------- Text as a control ---------- */

  .trigger {
    position: absolute;
    inset: 0;
    padding: 0;
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: inherit;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .trigger:hover {
      background: var(--ui-fill);
    }
  }

  .trigger:active {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  .trigger:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .trigger::after {
      content: "";
      position: absolute;
      inset-block: min(0px, calc((100% - 40px) / 2));
      inset-inline: 0;
    }
  }

  /* ---------- Editor ---------- */

  .input {
    position: absolute;
    inset: 0;
    z-index: 2;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    padding: var(--inline-pad-y) var(--inline-pad-x);
    border: 0;
    border-radius: inherit;
    background: none;
    overflow: hidden;
    resize: none;
    outline: none;
    caret-color: var(--ui-foreground);
  }

  .input::placeholder {
    color: var(--ui-subtle);
    opacity: 1;
  }

  .input[aria-busy] {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--inline-dim)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--inline-dim)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    mask-position: 100% 0;
    animation:
      inline-dim var(--ui-dur-base) var(--ui-ease-color) 300ms forwards,
      inline-sweep var(--ui-dur-sweep) linear 300ms infinite;
  }

  @keyframes inline-dim {
    to {
      --inline-dim: 0.45;
    }
  }

  @keyframes inline-sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  /* iOS zooms into fields under 16px; the text grows too so the two still match. */
  @media (pointer: coarse) {
    .text,
    .input {
      font-size: max(1em, var(--ui-text-touch));
    }
  }

  /* ---------- Error ---------- */

  .message {
    position: absolute;
    inset-block-start: calc(100% + var(--ui-space-1));
    inset-inline-start: 0;
    z-index: 10;
    pointer-events: none;
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    width: max-content;
    max-width: min(320px, calc(100vw - var(--ui-space-6)));
    padding: var(--ui-space-1) var(--ui-space-3) var(--ui-space-1) var(--ui-space-2);
    border-radius: var(--ui-radius-sm);
    background: var(--ui-surface);
    box-shadow:
      0 0 0 var(--ui-hairline) var(--ui-border-strong),
      var(--ui-shadow-raised);
    color: var(--ui-danger-text);
    font: var(--ui-weight-regular) var(--ui-text-sm) / var(--ui-leading-md) var(--ui-font-sans);
    letter-spacing: normal;
    text-align: start;
    text-transform: none;
    white-space: normal;
    text-wrap: pretty;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      visibility 0s linear var(--ui-dur-instant);
  }

  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .errorIcon {
    flex-shrink: 0;
  }

  .error[data-shown] .errorText {
    animation: inline-error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes inline-error-swap {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .input[aria-busy] {
      animation: inline-dim var(--ui-dur-base) var(--ui-ease-color) 300ms forwards;
      mask-position: 0 0;
    }
    .error[data-shown] .errorText {
      animation: none;
    }
  }
}

"use client";

import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type KeyboardEvent,
  type MouseEvent,
} from "react";
import { Icon } from "../icons/icons";
import styles from "./inline-edit.module.css";

type TextTag = "span" | "strong" | "p" | "div" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6";

type InlineEditProps = {
  /** Accessible name of the input, such as "Event name". */
  label: string;
  /** Controlled text. Update it in `onCommit`, before any promise it returns settles. */
  value?: string;
  defaultValue?: string;
  /** Called with the trimmed text when it changed; return a promise to show saving, reject to show an error. */
  onCommit?: (value: string) => void | Promise<unknown>;
  onCancel?: () => void;
  /** Return an error message, or null when valid. Empty text is always refused. */
  validate?: (value: string) => string | null;
  /** Element to render the text as; it inherits its look from the parent or `className`. */
  as?: TextTag;
  /** Verb prefixed to the button's accessible name. */
  verb?: string;
  placeholder?: string;
  maxLength?: number;
  disabled?: boolean;
  className?: string;
};

const BLOCK = new Set<TextTag>(["p", "div", "h1", "h2", "h3", "h4", "h5", "h6"]);
const EMPTY = "Enter a name";

function offsetAt(node: Node | null, x: number, y: number) {
  if (!node || node.nodeType !== Node.TEXT_NODE) return null;
  const length = node.textContent?.length ?? 0;
  if (length > 500) return null;
  const range = document.createRange();
  let best = length;
  let bestScore = Infinity;
  for (let i = 0; i <= length; i++) {
    range.setStart(node, i);
    range.setEnd(node, i);
    const rect = range.getBoundingClientRect();
    const dy = y < rect.top ? rect.top - y : y > rect.bottom ? y - rect.bottom : 0;
    const score = dy * 1000 + Math.abs(x - rect.left);
    if (score < bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return best;
}

function messageOf(reason: unknown) {
  if (typeof reason === "string" && reason) return reason;
  if (reason instanceof Error && reason.message) return reason.message;
  return "Couldn’t save. Try again.";
}

/** Text that becomes an input in place, for renaming. */
export function InlineEdit({
  label,
  value,
  defaultValue = "",
  onCommit,
  onCancel,
  validate,
  as: Tag = "span",
  verb = "Rename",
  placeholder,
  maxLength,
  disabled = false,
  className,
}: InlineEditProps) {
  const id = useId();
  const errorId = `${id}-error`;
  const [inner, setInner] = useState(defaultValue);
  const current = value ?? inner;

  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  // Kept after the error clears so it can fade out.
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  const inputRef = useRef<HTMLTextAreaElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const entry = useRef<number | "all">("all");
  const returnFocus = useRef(false);
  // Updated synchronously: a blur during teardown must not commit twice.
  const live = useRef({ editing: false, saving: false });

  useLayoutEffect(() => {
    if (editing) {
      const input = inputRef.current;
      if (!input) return;
      input.focus({ preventScroll: true });
      const at = entry.current;
      if (at === "all") input.select();
      else input.setSelectionRange(at, at);
    } else if (returnFocus.current) {
      returnFocus.current = false;
      triggerRef.current?.focus({ preventScroll: true });
    }
  }, [editing]);

  function start(at: number | "all") {
    if (disabled) return;
    entry.current = at;
    live.current.editing = true;
    setDraft(current);
    setError(null);
    setEditing(true);
  }

  function finish(refocus: boolean) {
    returnFocus.current = refocus;
    live.current = { editing: false, saving: false };
    setError(null);
    setSaving(false);
    setEditing(false);
  }

  function check(text: string) {
    return validate?.(text) ?? (text ? null : EMPTY);
  }

  async function commit(fromKeyboard: boolean) {
    if (live.current.saving) return;
    const next = draft.trim();
    const problem = check(next);
    if (problem) {
      setError(problem);
      return;
    }
    if (next === current) {
      finish(fromKeyboard);
      return;
    }
    let result: void | Promise<unknown>;
    try {
      result = onCommit?.(next);
    } catch (reason) {
      setError(messageOf(reason));
      return;
    }
    if (result && typeof result.then === "function") {
      setError(null);
      setSaving(true);
      live.current.saving = true;
      try {
        await result;
      } catch (reason) {
        live.current.saving = false;
        setSaving(false);
        setError(messageOf(reason));
        return;
      }
    }
    if (value === undefined) setInner(next);
    finish(document.activeElement === inputRef.current);
  }

  function cancel() {
    finish(true);
    onCancel?.();
  }

  function onKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.nativeEvent.isComposing) return;
    if (event.key === "Enter") {
      event.preventDefault();
      void commit(true);
    } else if (event.key === "Escape") {
      // Stopped so an enclosing dialog doesn't also close.
      event.preventDefault();
      event.stopPropagation();
      if (!saving) cancel();
    }
  }

  function onChange(event: ChangeEvent<HTMLTextAreaElement>) {
    const next = event.currentTarget.value.replace(/\s*[\r\n]+\s*/g, " ");
    setDraft(next);
    if (error) setError(check(next.trim()));
  }

  function onClick(event: MouseEvent<HTMLButtonElement>) {
    const text = event.currentTarget.previousElementSibling?.firstChild ?? null;
    start(event.detail === 0 ? "all" : (offsetAt(text, event.clientX, event.clientY) ?? "all"));
  }

  const Root = BLOCK.has(Tag) ? "div" : "span";
  const shown = editing ? draft || placeholder || current : current || placeholder;
  const invalid = Boolean(error);

  return (
    <Root
      className={className ? `${styles.root} ${className}` : styles.root}
      data-block={Root === "div" || undefined}
      data-editing={editing || undefined}
      data-invalid={invalid || undefined}
      data-disabled={disabled || undefined}
    >
      {/* While editing, holds the hidden draft so the box sizes the textarea. */}
      <Tag className={styles.text} data-placeholder={(!current && !editing) || undefined} aria-hidden={editing || undefined}>
        {shown || "\u00a0"}
      </Tag>
      {!editing && !disabled && (
        <button
          ref={triggerRef}
          type="button"
          className={styles.trigger}
          aria-label={`${verb} ${current || label}`}
          onClick={onClick}
          onKeyDown={(event) => {
            if (event.key === "F2") {
              event.preventDefault();
              start("all");
            }
          }}
        />
      )}
      {editing && (
        <textarea
          ref={inputRef}
          className={styles.input}
          value={draft}
          rows={1}
          placeholder={placeholder}
          maxLength={maxLength}
          readOnly={saving}
          aria-label={label}
          aria-busy={saving || undefined}
          aria-invalid={invalid || undefined}
          aria-describedby={invalid ? errorId : undefined}
          enterKeyHint="done"
          spellCheck
          onChange={onChange}
          onKeyDown={onKeyDown}
          onBlur={() => {
            if (live.current.editing && !live.current.saving) void commit(false);
          }}
        />
      )}
      <span className={styles.message} aria-live="polite">
        {lastError && (
          <span id={errorId} className={styles.error} data-shown={editing && error ? "" : undefined}>
            <Icon name="alert" className={styles.errorIcon} />
            <span key={lastError} className={styles.errorText}>
              {lastError}
            </span>
          </span>
        )}
      </span>
    </Root>
  );
}
